#!/usr/bin/env bash
set -euo pipefail

if [[ $# != 1 ]]; then
  echo "Usage: $0 /tmp/drift-cdg290-offline-<run-id>/demo.env" >&2
  exit 2
fi
env_file="$1"
case "$env_file" in
  /tmp/drift-cdg290-offline-*/demo.env) ;;
  *) echo "Refusing a configuration file outside the generated /tmp demo directory." >&2; exit 2 ;;
esac
[[ -f "$env_file" ]] || { echo "Demo environment file not found." >&2; exit 2; }
# The file is generated by start-postgres.sh with mode 600 and contains only shell-safe values.
# shellcheck disable=SC1090
source "$env_file"

read -r -s -p "Choose a local-only demo password (8+ chars, mixed case and a number): " DEMO_PASSWORD
echo
export DEMO_PASSWORD
node "$(dirname "$0")/seed-demo-tenant.mjs" "$env_file"
unset DEMO_PASSWORD
